import{_ as a,o as i,c as t,ae as r}from"./chunks/framework.C4zpkcTP.js";const u=JSON.parse('{"title":"AI credentials","description":"","frontmatter":{},"headers":[],"relativePath":"credentials.md","filePath":"credentials.md"}'),n={name:"credentials.md"};function o(l,e,d,s,c,h){return i(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="ai-credentials" tabindex="-1">AI credentials <a class="header-anchor" href="#ai-credentials" aria-label="Permalink to &quot;AI credentials&quot;">​</a></h1><p>AI credentials are how external agents authenticate to DockPilot. They are created by administrators and managed through the admin API and dashboard.</p><h2 id="creating-a-credential" tabindex="-1">Creating a credential <a class="header-anchor" href="#creating-a-credential" aria-label="Permalink to &quot;Creating a credential&quot;">​</a></h2><p>An administrator creates an AI credential with:</p><ul><li>a name,</li><li>an optional description,</li><li>an optional agent identity,</li><li>a permission level,</li><li>an optional expiry of 1 to 365 days,</li><li>an optional metadata object.</li></ul><p>The create response is the only place the raw token is ever returned.</p><h2 id="token-handling" tabindex="-1">Token handling <a class="header-anchor" href="#token-handling" aria-label="Permalink to &quot;Token handling&quot;">​</a></h2><ul><li>Tokens are 32 random bytes rendered as <code>dpai_</code> followed by 43 URL-safe characters.</li><li>The raw token is returned exactly once and never stored in plaintext.</li><li>Only an HMAC-SHA256 digest is persisted, keyed by <code>MCP_TOKEN_SECRET</code>.</li><li>Token prefixes are stored so an administrator can identify a credential without seeing the secret.</li></ul><h2 id="lifecycle" tabindex="-1">Lifecycle <a class="header-anchor" href="#lifecycle" aria-label="Permalink to &quot;Lifecycle&quot;">​</a></h2><p>Each credential records:</p><ul><li><code>createdAt</code></li><li><code>lastUsedAt</code></li><li><code>expiresAt</code></li><li><code>revokedAt</code></li><li><code>disabledAt</code></li></ul><p>A credential can be revoked immediately, which rejects subsequent authentication. Expired and disabled credentials are also rejected.</p><h2 id="permission-scoping" tabindex="-1">Permission scoping <a class="header-anchor" href="#permission-scoping" aria-label="Permalink to &quot;Permission scoping&quot;">​</a></h2><p>Credentials are created with a permission level of <code>read</code>, <code>write</code>, or <code>destructive</code>. The stored permission level is what the server enforces on every MCP tool call. No tool accepts a permission, role, or scope parameter, so a credential cannot raise its own privilege.</p><h2 id="operational-guidance" tabindex="-1">Operational guidance <a class="header-anchor" href="#operational-guidance" aria-label="Permalink to &quot;Operational guidance&quot;">​</a></h2><ul><li>Treat each AI credential as a production secret.</li><li>Grant the lowest permission level that works.</li><li>Prefer expiries for temporary agents.</li><li>Revoke credentials you no longer use.</li><li>Keep <code>MCP_ENABLED=false</code> on instances where no agent should connect.</li></ul>',16)])])}const m=a(n,[["render",o]]);export{u as __pageData,m as default};
